-- King / Queen (class 64), step 8: the commander grows with you, and the King's styles get their own procs.
-- * Fealty becomes a hybrid spell list: only your best commander (and best tier of each retainer) is listed,
--   so the Squire "grows" into Shieldbearer, Sergeant-at-Arms, Knight-Errant and Knight.
-- * Each rank keeps everything the last had, plus:
--     Squire: short sword, cloth gambeson, Squire's Cut (anytime); weaker than normal (80% stats)
--     Shieldbearer: leather, small shield, Shieldbearer's Challenge (taunt), Halt, Knave! (ranged snare shout)
--     Sergeant-at-Arms: studded, Shield Bash (after a block: 5 s stun) -> Crushing Rebuttal (bleed),
--                       Call to Arms (party endurance regeneration)
--     Knight-Errant: chain, medium shield, parry; Steel Parry (after a parry: slowed) -> Knight's Riposte (hindered);
--                    stronger Call to Arms + Errant's Insight (party power regeneration)
--     Knight: plate, cloak, Oathkeeper's Verdict (armor debuff) -> Excalibur's Oath (strength debuff), Charge;
--             strongest endurance + power chants + Knight's Vigil (party health regeneration)
--   Pets cannot hold pulsing chants, so the chants are 10-minute party auras the commander keeps up.
-- * New procs for all King styles but Crown's Edge (spells 64400-64413).
-- Spells 64300-64413 use tooltip IDs 21000+.

UPDATE Specialization SET Implementation = 'DOL.GS.LiveSpellHybridSpecialization' WHERE KeyName = 'Fealty';
DELETE FROM StyleXSpell WHERE StyleXSpell_ID LIKE 'king_style_%';
DELETE FROM NPCEquipment WHERE TemplateID LIKE 'king_cmd_%';
UPDATE NpcTemplate SET ParryChance = 0, BlockChance = 0, EvadeChance = 0, Strength = 80, Constitution = 85, Dexterity = 80, Quickness = 80, Styles = '56|640', Spells = '', Abilities = '' WHERE TemplateId = 64001;
