UPDATE NpcTemplate SET ParryChance = 25, BlockChance = 25, EvadeChance = 0, Strength = 120, Constitution = 125, Dexterity = 120, Quickness = 120, Styles = '56|640;66|640;61|640;62|640;63|640;60|640;70|640;67|640', Spells = '64300;64303;64305;64306', Abilities = 'Charge|1' WHERE TemplateId = 64005;

-- UNDO
UPDATE Specialization SET Implementation = NULL WHERE KeyName = 'Fealty';
DELETE FROM StyleXSpell WHERE StyleXSpell_ID LIKE 'king_style_%' OR StyleXSpell_ID LIKE 'king_cmdstyle_%';
DELETE FROM Style WHERE ClassId = 640;
DELETE FROM Spell WHERE SpellID BETWEEN 64300 AND 64499;
DELETE FROM NPCEquipment WHERE TemplateID LIKE 'king_cmd_%';
